function evidence = f90_xmed03_extract_evidence(modelPath, outDir)
%F90_XMED03_EXTRACT_EVIDENCE Simulate and write normalized score-free evidence.
%
% MATLAB owns the static audit, all eight official simulations, and the
% deterministic evidence projection.  No score, threshold, group utility,
% or scorer process is evaluated here.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end

root = localProjectRoot;
task = f90_xmed03_definition;
generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XMED03:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
evaluationSubject = lower(strtrim(string(getenv("SIMUVERITY_EVALUATION_SUBJECT"))));
assert(any(evaluationSubject == ["candidate", "reference"]), ...
    "SimuVerity:F90:XMED03:EvaluationSubject", "Unsupported evaluation subject.");
assert(isfile(modelPath), "SimuVerity:F90:XMED03:ModelMissing", ...
    "Model under evaluation is missing: %s", modelPath);
if ~isfolder(outDir), mkdir(outDir); end
evidencePath = fullfile(outDir, "evidence.json");
assert(~isfile(evidencePath), "SimuVerity:F90:XMED03:OutputReuse", ...
    "Evidence already exists for GenerationRunId %s.", generationRunId);

addpath(fullfile(root, "scripts", "xp9"), "-begin");
metricPath = fullfile(outDir, "scenario_metrics.json");
staticAuditPath = fullfile(outDir, "static_audit.json");

% The static audit updates the model, so install nominal public inputs first.
localAssignScenario(task.scenarios(1));
try
    staticAudit = f90_xmed03_static_audit(modelPath);
catch auditError
    staticAudit = localFailedStaticAudit(modelPath, auditError);
end
localWriteJson(staticAuditPath, staticAudit);

try
    metrics = f90_xmed03_probe_reference_metrics(modelPath, metricPath);
catch simulationError
    metrics = struct( ...
        "schema", ...
            "simuverity.formal90-xmed03-reference-metrics.v1", ...
        "task_id", "F90-XMED-03", ...
        "generation_run_id", generationRunId, ...
        "matlab_release", string(version("-release")), ...
        "model", string(modelPath), ...
        "scenarios", struct([]), ...
        "all_valid", false, ...
        "error", string(getReport(simulationError, "extended", ...
            "hyperlinks", "off")));
    localWriteJson(metricPath, metrics);
end

rows = metrics.scenarios;
for index = 1:numel(rows)
    rows(index).input_file_presence = localInputFilePresence(string(rows(index).id));
end

officialPath = string(task.runner.official_scenarios);
referencePath = string(task.runner.reference_model);
evidence = struct( ...
    "schema", ...
        "simuverity.formal90-xmed03-normalized-evidence.v1", ...
    "task_id", "F90-XMED-03", ...
    "evaluation_subject", evaluationSubject, ...
    "policy_id", ...
        "simuverity-101-v1:f90-xmed-03:scoring", ...
    "extraction_only", true, ...
    "contains_score_or_threshold_decisions", false, ...
    "reference_model", referencePath, ...
    "reference_model_file_presence", ...
        lower(string(xp9_file_presence_file(referencePath))), ...
    "official_scenarios", officialPath, ...
    "official_scenarios_file_presence", ...
        lower(string(xp9_file_presence_file(officialPath))), ...
    "subject_model", string(modelPath), ...
    "subject_model_file_presence", ...
        lower(string(xp9_file_presence_file(modelPath))), ...
    "source_contract", struct( ...
        "scenario_metrics_schema", string(metrics.schema), ...
        "static_audit_schema", string(staticAudit.schema)), ...
    "provenance", struct( ...
        "handoff_schema", ...
            "simuverity.formal90-xmed03-runtime-handoff.v1", ...
        "generation_run_id", generationRunId, ...
        "matlab_release", string(version("-release")), ...
        "raw_scenario_metrics", string(metricPath), ...
        "raw_scenario_metrics_file_presence", ...
            lower(string(xp9_file_presence_file(metricPath))), ...
        "raw_static_audit", string(staticAuditPath), ...
        "raw_static_audit_file_presence", ...
            lower(string(xp9_file_presence_file(staticAuditPath)))), ...
    "static_audit", staticAudit, ...
    "scenarios", rows, ...
    "all_valid", logical(metrics.all_valid), ...
    "evidence_limitations", [ ...
        "slow_high_peep has one complete post-step breath in the saved 24 s evidence, so per-breath recovery is unavailable there"; ...
        "saved evidence contains breath aggregates but no breath-level pressure/flow arrays; D does not score transient pressure overshoot"; ...
        "saved evidence contains no raw within-breath traces; D does not score sub-breath response latency"]);
localWriteJson(evidencePath, evidence);
fprintf("F90_XMED03_EVIDENCE scenarios=%d all_valid=%d output=%s\n", ...
    numel(rows), logical(metrics.all_valid), evidencePath);
end

function localAssignScenario(scenario)
names = string(fieldnames(scenario));
for index = 1:numel(names)
    name = names(index);
    if name == "id", continue; end
    assignin("base", name, scenario.(name));
end
end

function presence = localInputFilePresence(id)
switch id
    case "nominal_targets"
        presence = "present";
    case "compliance_mismatch"
        presence = "present";
    case "resistance_mismatch"
        presence = "present";
    case "divergent_target_step"
        presence = "present";
    case "rapid_low_compliance"
        presence = "present";
    case "slow_high_peep"
        presence = "present";
    case "crossed_mechanics"
        presence = "present";
    case "joint_boundary"
        presence = "present";
    otherwise
        error("SimuVerity:F90:XMED03:ScenarioIdentity", ...
            "Unknown official scenario id: %s", id);
end
end

function audit = localFailedStaticAudit(modelPath, auditError)
checks = struct( ...
    "shared_physical_source", false, ...
    "two_patient_resistive_mechanics", false, ...
    "two_patient_compliance_mechanics", false, ...
    "two_commanded_physical_branch_elements", false, ...
    "two_measured_feedback_paths", false, ...
    "physical_pressure_flow_volume_provenance", false, ...
    "branch_command_output_present", false);
audit = struct( ...
    "schema", "simuverity.formal90-xmed03-static-audit.v1", ...
    "model_path", string(modelPath), ...
    "required_output_physical_provenance", [false, false, false], ...
    "checks", checks, ...
    "failed_checks", "static_audit_exception", ...
    "pass", false, ...
    "error", string(getReport(auditError, "extended", ...
        "hyperlinks", "off")));
end

function root = localProjectRoot
root = fileparts(mfilename("fullpath"));
for level = 1:4
    root = fileparts(root);
end
end

function localWriteJson(pathValue, value)
folder = fileparts(pathValue);
if ~isfolder(folder), mkdir(folder); end
fid = fopen(pathValue, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:F90:XMED03:WriteJson", ...
    "Unable to write %s.", pathValue);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
end
